            C++

    #include <bits/stdc++.h>
using namespace std;

struct C {
    int a;

  	// Defining ++ for struct C
    C& operator++() {
        ++a;
        return *this;
    }
};

int main() {
    vector<C> v(5);

    // Fill the vector starting from Counter{1}
    iota(v.begin(), v.end(), C{1});

    for (auto i: v) {
        cout << i.a << " ";
    }
    return 0;
}

Output1 2 3 4 5 Time Complexity: O(n), where n is the number of elements in the given range.Auxiliary Space: O(1)Explanation: For iota() to work, the ++ operator must be defined for data type used in the range. So, for custom data type, we need to manually implement the ++ operator as done in struct C.
